"use client"

import { Checkbox as CheckboxPrimitive } from "@base-ui/react/checkbox"
import { Icon } from "@iconify/react"

import { cn } from "@/lib/utils"

function Checkbox({ className, ...props }: CheckboxPrimitive.Root.Props) {
  return (
    <CheckboxPrimitive.Root
      data-slot="checkbox"
      className={cn(
        "peer inline-flex items-center justify-center h-4 w-4 shrink-0 rounded border border-border",
        "bg-input [box-shadow:var(--shadow-inset)]",
        "transition-[background-color,box-shadow,border-color] duration-fast",
        "hover:border-ring/40",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40",
        "data-disabled:cursor-not-allowed data-disabled:opacity-50",
        "data-checked:bg-primary data-checked:[background-image:var(--metal)] data-checked:border-transparent data-checked:text-primary-foreground data-checked:[box-shadow:var(--shadow-primary)]",
        "data-indeterminate:bg-primary data-indeterminate:[background-image:var(--metal)] data-indeterminate:border-transparent data-indeterminate:text-primary-foreground data-indeterminate:[box-shadow:var(--shadow-primary)]",
        className
      )}
      {...props}
    >
      <CheckboxPrimitive.Indicator data-slot="checkbox-indicator" className="size-full flex items-center justify-center text-current">
        {props.indeterminate ? (
          <Icon icon="ph:minus" className="h-3 w-3" />
        ) : (
          <Icon icon="ph:check" className="h-3 w-3" />
        )}
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  )
}
Checkbox.displayName = "Checkbox"

export { Checkbox }
